using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Threading.Tasks;

// Host-only workaround: all Android resource compilation/linking is performed by
// the official AAPT2. Its documented directory output avoids a native ZIP writer
// crash on this host; .NET packages those exact generated bytes for normal AGP.
internal static class Aapt2DirectoryWrapper
{
    private static string ToolPath
    {
        get { return File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "real-aapt2-path.txt")).Trim(); }
    }

    public static int Main(string[] args)
    {
        Console.InputEncoding = new UTF8Encoding(false);
        Console.OutputEncoding = new UTF8Encoding(false);
        if (args.Length == 1 && (args[0] == "daemon" || args[0] == "m"))
        {
            Console.Out.WriteLine("Ready");
            Console.Out.Flush();
            while (true)
            {
                var command = new List<string>();
                string line;
                while ((line = Console.ReadLine()) != null && line.Length != 0) command.Add(line);
                if (command.Count == 0 && line == null) return 0;
                if (command.Count == 1 && command[0] == "quit")
                {
                    Console.Out.WriteLine("Exiting daemon");
                    return 0;
                }
                if (command.Count == 0) continue;
                int code = Execute(command.ToArray());
                if (code != 0) Console.Error.WriteLine("Error");
                Console.Error.WriteLine("Done");
                Console.Error.Flush();
            }
        }
        return Execute(args);
    }

    private static int Execute(string[] args)
    {
        string directory = null;
        string output = null;
        string trace = null;
        try
        {
            var actual = new List<string>(args);
            // AGP uses the short protocol aliases c/l (Aapt2DaemonUtil).
            if (actual.Count > 0 && actual[0] == "l") actual[0] = "link";
            if (actual.Count > 0 && actual[0] == "c") actual[0] = "compile";
            if (actual.Count > 0 && (actual[0] == "link" || actual[0] == "convert" || actual[0] == "optimize"))
            {
                string traceDirectory = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "trace");
                Directory.CreateDirectory(traceDirectory);
                trace = Path.Combine(traceDirectory, DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff") + "-" + Guid.NewGuid().ToString("N"));
                File.WriteAllLines(trace + ".request.txt", args, new UTF8Encoding(false));
            }
            if (actual.Count > 0 && actual[0] == "link" && !actual.Contains("--output-to-dir"))
            {
                int outputIndex = actual.IndexOf("-o");
                if (outputIndex < 0 || outputIndex + 1 >= actual.Count) throw new InvalidOperationException("Missing AAPT2 output argument.");
                output = Path.GetFullPath(actual[outputIndex + 1]);
                AssertWorkspacePath(output);
                directory = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "d", Guid.NewGuid().ToString("N").Substring(0, 12));
                AssertWorkspacePath(directory);
                Directory.CreateDirectory(directory);
                // DirectoryArchiveWriter requires resource subdirectories to
                // exist. AGP supplies individual <folder>_<name>.flat inputs.
                foreach (string argument in actual)
                {
                    string fileName = Path.GetFileName(argument);
                    int separator = fileName.IndexOf('_');
                    if (!fileName.EndsWith(".flat", StringComparison.OrdinalIgnoreCase) || separator <= 0) continue;
                    string resourceFolder = fileName.Substring(0, separator);
                    foreach (char character in resourceFolder)
                        if (!(char.IsLetterOrDigit(character) || character == '-' || character == '+'))
                            throw new IOException("Invalid compiled resource directory.");
                    Directory.CreateDirectory(Path.Combine(directory, "res", resourceFolder));
                }
                actual[outputIndex + 1] = directory;
                actual.Add("--output-to-dir");
            }
            if (trace != null) File.WriteAllLines(trace + ".actual.txt", actual.ToArray(), new UTF8Encoding(false));
            var start = new ProcessStartInfo(ToolPath, JoinArguments(actual))
            {
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                StandardOutputEncoding = new UTF8Encoding(false),
                StandardErrorEncoding = new UTF8Encoding(false)
            };
            using (var process = Process.Start(start))
            {
                Task<string> stdout = process.StandardOutput.ReadToEndAsync();
                Task<string> stderr = process.StandardError.ReadToEndAsync();
                process.WaitForExit();
                string outputText = stdout.GetAwaiter().GetResult();
                string errorText = stderr.GetAwaiter().GetResult();
                if (trace != null)
                {
                    File.WriteAllText(trace + ".stdout.txt", outputText, new UTF8Encoding(false));
                    File.WriteAllText(trace + ".stderr.txt", errorText, new UTF8Encoding(false));
                    File.WriteAllText(trace + ".exit.txt", process.ExitCode.ToString(), new UTF8Encoding(false));
                }
                Console.Out.Write(outputText);
                Console.Error.Write(errorText);
                if (process.ExitCode != 0) return process.ExitCode;
            }
            if (directory != null)
            {
                // Android target >=30 requires the resource table uncompressed.
                // Store every resource, allowing the regular AGP packaging step
                // to retain complete entries and apply its normal alignment.
                StoreZip(directory, output);
            }
            return 0;
        }
        catch (Exception error)
        {
            Console.Error.WriteLine("error: AAPT2 directory wrapper: " + error.Message);
            return 1;
        }
        finally
        {
            if (directory != null && Directory.Exists(directory))
            {
                AssertWorkspacePath(directory);
                Directory.Delete(directory, true);
            }
        }
    }

    private static void AssertWorkspacePath(string path)
    {
        string workspace = Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "..", ".."));
        string fullPath = Path.GetFullPath(path);
        if (!fullPath.StartsWith(workspace.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar,
                                 StringComparison.OrdinalIgnoreCase))
            throw new IOException("Wrapper output must remain inside its workspace.");
    }

    private sealed class StoredEntry
    {
        public byte[] Name;
        public uint Crc;
        public uint Size;
        public uint Offset;
    }

    private static void StoreZip(string directory, string output)
    {
        var files = Directory.GetFiles(directory, "*", SearchOption.AllDirectories);
        Array.Sort(files, StringComparer.Ordinal);
        if (files.Length >= ushort.MaxValue) throw new IOException("Too many generated resources for classic ZIP.");
        var entries = new List<StoredEntry>();
        using (var stream = new FileStream(output, FileMode.Create, FileAccess.Write, FileShare.None))
        using (var writer = new BinaryWriter(stream, Encoding.UTF8))
        {
            foreach (string path in files)
            {
                var entry = new StoredEntry();
                entry.Name = Encoding.UTF8.GetBytes(path.Substring(directory.Length + 1).Replace('\\', '/'));
                entry.Size = checked((uint)new FileInfo(path).Length);
                entry.Offset = checked((uint)stream.Position);
                if (entry.Name.Length > ushort.MaxValue) throw new IOException("Generated resource path is too long.");
                using (var source = File.OpenRead(path)) entry.Crc = Crc32(source);
                writer.Write(0x04034b50u); writer.Write((ushort)20); writer.Write((ushort)0x800);
                writer.Write((ushort)0); writer.Write((ushort)0); writer.Write((ushort)33);
                writer.Write(entry.Crc); writer.Write(entry.Size); writer.Write(entry.Size);
                writer.Write((ushort)entry.Name.Length); writer.Write((ushort)0); writer.Write(entry.Name);
                using (var source = File.OpenRead(path)) source.CopyTo(stream);
                entries.Add(entry);
            }
            uint centralOffset = checked((uint)stream.Position);
            foreach (var entry in entries)
            {
                writer.Write(0x02014b50u); writer.Write((ushort)20); writer.Write((ushort)20);
                writer.Write((ushort)0x800); writer.Write((ushort)0); writer.Write((ushort)0); writer.Write((ushort)33);
                writer.Write(entry.Crc); writer.Write(entry.Size); writer.Write(entry.Size);
                writer.Write((ushort)entry.Name.Length); writer.Write((ushort)0); writer.Write((ushort)0);
                writer.Write((ushort)0); writer.Write((ushort)0); writer.Write(0u); writer.Write(entry.Offset);
                writer.Write(entry.Name);
            }
            uint centralSize = checked((uint)(stream.Position - centralOffset));
            writer.Write(0x06054b50u); writer.Write((ushort)0); writer.Write((ushort)0);
            writer.Write((ushort)entries.Count); writer.Write((ushort)entries.Count);
            writer.Write(centralSize); writer.Write(centralOffset); writer.Write((ushort)0);
            writer.Flush(); stream.Flush(true);
        }
    }

    private static uint Crc32(Stream source)
    {
        uint crc = uint.MaxValue;
        var buffer = new byte[65536];
        int count;
        while ((count = source.Read(buffer, 0, buffer.Length)) != 0)
        {
            for (int i = 0; i < count; i++)
            {
                crc ^= buffer[i];
                for (int bit = 0; bit < 8; bit++) crc = (crc >> 1) ^ ((crc & 1) != 0 ? 0xedb88320u : 0u);
            }
        }
        return ~crc;
    }

    private static string JoinArguments(IEnumerable<string> args)
    {
        var result = new StringBuilder();
        foreach (string argument in args)
        {
            if (result.Length != 0) result.Append(' ');
            result.Append('"');
            int slashes = 0;
            foreach (char character in argument)
            {
                if (character == '\\') { slashes++; continue; }
                if (character == '"') result.Append('\\', slashes * 2 + 1);
                else result.Append('\\', slashes);
                slashes = 0;
                result.Append(character);
            }
            result.Append('\\', slashes * 2);
            result.Append('"');
        }
        return result.ToString();
    }
}
